#include <bits/stdc++.h>
using namespace std;

using ll = long long;

static constexpr ll MOD = 1000000007LL;

ll modPow(ll base, ll exponent) {
    ll result = 1;
    while (exponent > 0) {
        if (exponent & 1LL) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1LL;
    }
    return result;
}

class Solver {
    int levels, length;
    string pattern;
    vector<ll> fib, pow2Fib;
    vector<ll> dp, starts, ends, occurrences;

    size_t index(int level, int left, int right) const {
        return (static_cast<size_t>(level) * length + left) * length + right;
    }

    ll baseValue(int level, int left, int right) const {
        return left == right && ((level == 0 && pattern[left] == '0') ||
                                 (level == 1 && pattern[left] == '1'));
    }

    ll countOccurrences(int level, int left, int right) {
        if (level <= 1) return baseValue(level, left, right);

        ll& result = occurrences[index(level, left, right)];
        if (result != -1) return result;

        result = (countOccurrences(level - 1, left, right) +
                  countOccurrences(level - 2, left, right)) % MOD;

        for (int cut = left; cut < right; ++cut) {
            result += countOccurrences(level - 1, left, cut) *
                      countOccurrences(level - 2, cut + 1, right) % MOD;
            if (result >= MOD) result -= MOD;
        }
        return result;
    }

    ll countStarts(int level, int left, int right) {
        if (level <= 1) return baseValue(level, left, right);

        ll& result = starts[index(level, left, right)];
        if (result != -1) return result;

        result = countStarts(level - 1, left, right) * pow2Fib[level - 2] % MOD;
        result += countStarts(level - 2, left, right);
        if (result >= MOD) result -= MOD;

        for (int cut = left; cut < right; ++cut) {
            result += countOccurrences(level - 1, left, cut) *
                      countStarts(level - 2, cut + 1, right) % MOD;
            if (result >= MOD) result -= MOD;
        }
        return result;
    }

    ll countEnds(int level, int left, int right) {
        if (level <= 1) return baseValue(level, left, right);

        ll& result = ends[index(level, left, right)];
        if (result != -1) return result;

        result = countEnds(level - 2, left, right) * pow2Fib[level - 1] % MOD;
        result += countEnds(level - 1, left, right);
        if (result >= MOD) result -= MOD;

        for (int cut = left; cut < right; ++cut) {
            result += countEnds(level - 1, left, cut) *
                      countOccurrences(level - 2, cut + 1, right) % MOD;
            if (result >= MOD) result -= MOD;
        }
        return result;
    }

    ll solveDP(int level, int left, int right) {
        if (level <= 1) return baseValue(level, left, right);

        ll& result = dp[index(level, left, right)];
        if (result != -1) return result;

        result = solveDP(level - 1, left, right) * pow2Fib[level - 2] % MOD;
        result += solveDP(level - 2, left, right) * pow2Fib[level - 1] % MOD;
        result %= MOD;

        for (int cut = left; cut < right; ++cut) {
            result += countEnds(level - 1, left, cut) *
                      countStarts(level - 2, cut + 1, right) % MOD;
            if (result >= MOD) result -= MOD;
        }
        return result;
    }

public:
    Solver(int levelCount, string value)
        : levels(levelCount), length(static_cast<int>(value.size())),
          pattern(std::move(value)), fib(levels + 1),
          pow2Fib(levels + 1) {
        if (levels >= 0) fib[0] = 1;
        if (levels >= 1) fib[1] = 1;
        for (int i = 2; i <= levels; ++i) {
            fib[i] = (fib[i - 1] + fib[i - 2]) % (MOD - 1);
        }
        for (int i = 0; i <= levels; ++i) {
            pow2Fib[i] = modPow(2, fib[i]);
        }

        size_t total = static_cast<size_t>(levels + 1) * length * length;
        dp.assign(total, -1);
        starts.assign(total, -1);
        ends.assign(total, -1);
        occurrences.assign(total, -1);
    }

    ll solve() {
        if (length == 0) return 0;
        return solveDP(levels, 0, length - 1);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, x;
    string s;
    cin >> n >> x >> s;

    Solver solver(static_cast<int>(x), s);
    cout << solver.solve() << '\n';
    return 0;
}

