struct State {
    vector<ll> count, start, finish, answer;

    explicit State(size_t size = 0)
        : count(size, 0), start(size, 0), finish(size, 0), answer(size, 0) {}
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n, x;
    string s;
    cin >> n >> x >> s;

    unordered_map<string, int> id;
    vector<string> strings;

    const size_t maxSubstrings = s.size() * (s.size() + 1) / 2;
    id.reserve(maxSubstrings * 2 + 1);
    strings.reserve(maxSubstrings);

    for (size_t i = 0; i < s.size(); ++i) {
        string current;
        current.reserve(s.size() - i);

        for (size_t j = i; j < s.size(); ++j) {
            current.push_back(s[j]);
            if (id.find(current) == id.end()) {
                int newId = static_cast<int>(strings.size());
                id.emplace(current, newId);
                strings.push_back(current);
            }
        }
    }

    const int states = static_cast<int>(strings.size());
    vector<vector<pair<int, int>>> splits(states);

    for (int index = 0; index < states; ++index) {
        const string& current = strings[index];
        splits[index].reserve(current.size() > 0 ? current.size() - 1 : 0);

        for (size_t cut = 1; cut < current.size(); ++cut) {
            auto leftIt = id.find(current.substr(0, cut));
            auto rightIt = id.find(current.substr(cut));
            splits[index].emplace_back(leftIt->second, rightIt->second);
        }
    }

    size_t levels = static_cast<size_t>(max(1LL, x) + 1);
    vector<ll> fibonacci(levels, 1);
    vector<ll> powerOfTwo(levels, 2);

    for (size_t i = 2; i < levels; ++i) {
        fibonacci[i] = (fibonacci[i - 1] + fibonacci[i - 2]) % (MOD - 1);
    }
    for (size_t i = 0; i < levels; ++i) {
        powerOfTwo[i] = modPower(2, fibonacci[i]);
    }

    State previousTwo(states);
    State previous(states);

    auto zeroIt = id.find("0");
    if (zeroIt != id.end()) {
        int index = zeroIt->second;
        previousTwo.count[index] = 1;
        previousTwo.start[index] = 1;
        previousTwo.finish[index] = 1;
        previousTwo.answer[index] = 1;
    }

    auto oneIt = id.find("1");
    if (oneIt != id.end()) {
        int index = oneIt->second;
        previous.count[index] = 1;
        previous.start[index] = 1;
        previous.finish[index] = 1;
        previous.answer[index] = 1;
    }

    int target = id.find(s)->second;

    if (x == 0) {
        cout << previousTwo.answer[target] << '\n';
        return 0;
    }

    if (x == 1) {
        cout << previous.answer[target] << '\n';
        return 0;
    }

    for (ll level = 2; level <= x; ++level) {
        State current(states);
        ll leftMultiplier = powerOfTwo[static_cast<size_t>(level - 2)];
        ll rightMultiplier = powerOfTwo[static_cast<size_t>(level - 1)];

        for (int index = 0; index < states; ++index) {
            ll countValue =
                (previous.count[index] + previousTwo.count[index]) % MOD;

            ll startValue =
                (previous.start[index] * leftMultiplier +
                 previousTwo.start[index]) % MOD;

            ll finishValue =
                (previousTwo.finish[index] * rightMultiplier +
                 previous.finish[index]) % MOD;

            ll answerValue =
                (previous.answer[index] * leftMultiplier +
                 previousTwo.answer[index] * rightMultiplier) % MOD;

            for (const auto& [left, right] : splits[index]) {
                countValue += previous.count[left] * previousTwo.count[right] % MOD;
                if (countValue >= MOD) countValue -= MOD;

                startValue += previous.count[left] * previousTwo.start[right] % MOD;
                if (startValue >= MOD) startValue -= MOD;

                finishValue += previous.finish[left] * previousTwo.count[right] % MOD;
                if (finishValue >= MOD) finishValue -= MOD;

                answerValue += previous.finish[left] * previousTwo.start[right] % MOD;
                if (answerValue >= MOD) answerValue -= MOD;
            }

            current.count[index] = countValue;
            current.start[index] = startValue;
            current.finish[index] = finishValue;
            current.answer[index] = answerValue;
        }

        previousTwo = std::move(previous);
        previous = std::move(current);
    }

    cout << previous.answer[target] << '\n';
    return 0;
}

